package com.etic.licensecontrol.audit;
import com.etic.licensecontrol.common.CrudService;import java.util.*;import org.springframework.web.bind.annotation.*;
// LEGACY TEMPORAL: license_validation_events conserva Id_Application; su filtro histórico usa system_application_links.
@RestController @RequestMapping("/api/admin") public class OverviewController {private final CrudService c;OverviewController(CrudService c){this.c=c;}@org.springframework.beans.factory.annotation.Autowired private com.etic.licensecontrol.licensing.EntitlementService entitlements;@GetMapping("/dashboard")Map<String,Object>dashboard(){return entitlements.dashboard();}@GetMapping("/audit")Map<String,Object>audit(@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(required=false)String user,@RequestParam(required=false)String system,@RequestParam(required=false)String eventType,@RequestParam(required=false)String result,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="")String search){Map<String,Object>p=new HashMap<>();p.put("size",Math.min(Math.max(size,1),100));p.put("offset",Math.max(page,0)*Math.min(Math.max(size,1),100));p.put("search","%"+search+"%");p.put("from",blank(from));p.put("to",blank(to));p.put("user",blank(user));p.put("system",blank(system));p.put("event",blank(eventType));p.put("result",blank(result));p.put("success",result==null||result.isBlank()?null:"SUCCESS".equals(result)?1:0);return Map.of("authentication",c.db().queryForList("SELECT * FROM authentication_events WHERE (:from IS NULL OR Occurred_At>=:from) AND (:to IS NULL OR Occurred_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_User=:user) AND (:system IS NULL OR Id_System=:system) AND (:event IS NULL OR Event_Type=:event) AND (:success IS NULL OR Success=:success) AND (Username_Attempted LIKE :search OR Event_Type LIKE :search) ORDER BY Occurred_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p),"audit",c.db().queryForList("SELECT * FROM audit_events WHERE (:from IS NULL OR Created_At>=:from) AND (:to IS NULL OR Created_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_User=:user) AND (:system IS NULL OR Id_System=:system) AND (:event IS NULL OR Action=:event) AND (Action LIKE :search OR Entity_Type LIKE :search) ORDER BY Created_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p),"licenseValidation",c.db().queryForList("SELECT * FROM license_validation_events WHERE (:from IS NULL OR Created_At>=:from) AND (:to IS NULL OR Created_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_Usuario=:user) AND (:event IS NULL OR Event_Type=:event) AND (:result IS NULL OR Result=:result) AND (:system IS NULL OR Id_License IN (SELECT Id_License FROM licenses WHERE Id_System=:system) OR (Id_License IS NULL AND Id_Application IN (SELECT Id_Application FROM system_application_links WHERE Id_System=:system))) AND (CAST(Event_Type AS CHAR) LIKE :search) ORDER BY Created_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p));}private Object blank(String s){return s==null||s.isBlank()?null:s;}}
